<form method="post" id="iplm-form"><input type="hidden" name="iplm_csrf" value="<?= html_escape($csrf); ?>"><input type="hidden" name="version" value="<?= (int)$row['version']; ?>">
<?php if(array_sum($reference)>0): ?><div class="alert alert-info d-block"><strong>Referensi koleksi tercatat di aplikasi saat ini</strong><div>Judul cetak: <?= (int)$reference['print_titles']; ?> · Eksemplar cetak: <?= (int)$reference['print_copies']; ?> · Judul digital: <?= (int)$reference['digital_titles']; ?></div><p class="mb-2 mt-1">Ini data katalog jejaring perpustakaan ini, belum tentu seluruh koleksi atau kondisi akhir periode. Penambahan tahunan dan lisensi/eksemplar digital tidak dapat disimpulkan dari tanggal input katalog.</p><?php if($editable): ?><button type="button" class="btn btn-sm btn-outline-primary" id="use-collection-reference">Gunakan angka tercatat setelah saya periksa</button><?php endif; ?></div><?php endif; ?>
<div class="iplm-tabs" role="tablist" aria-label="Bagian formulir IPLM" data-iplm-tabs><?php $first=true;foreach($groups as$section=>$group): ?><button type="button" role="tab" id="tab-<?= html_escape($section); ?>" aria-controls="panel-<?= html_escape($section); ?>" aria-selected="<?= $first?'true':'false'; ?>"><?= html_escape($group['title']); ?> <span class="ms-1 opacity-75"><?= count($group['fields']); ?></span></button><?php $first=false;endforeach; ?></div>
<?php foreach($groups as$section=>$group): ?>
