<?php if($section==='evidence'): ?><div class="alert alert-info">Cukup satu tautan folder Google Drive untuk seluruh indikator. Kelompokkan dokumen di dalam folder menurut Koleksi, Tenaga, Pelayanan, dan Pengelolaan; pastikan admin dapat membacanya.</div><?php endif; ?>
<?php if($section==='evidence'&&array_filter($row['evidence'])): ?><details class="mb-3"><summary>Arsip tautan lama (tidak perlu diisi ulang)</summary><ul><?php foreach($row['evidence'] as$legacy_key=>$legacy_url): if(!preg_match('#^https://#i',(string)$legacy_url))continue; ?><li><a href="<?= html_escape($legacy_url); ?>" target="_blank" rel="noopener noreferrer"><?= html_escape($labels[$legacy_key]??$legacy_key); ?></a></li><?php endforeach; ?></ul></details><?php endif; ?>
