<div class="iplm-field-row"><div><label class="form-label" for="f_<?= html_escape($k); ?>"><?php if($f['excel_column']): ?><span class="badge bg-secondary-lt me-1"><?= html_escape($f['excel_column']); ?></span><?php endif; ?><?= html_escape($k==='evidence_url'?'Satu tautan folder bukti dukung':$f['label']); ?><?= $f['is_required']?' *':''; ?></label>
<?php if($f['kind']==='select'): ?>
<select id="f_<?= html_escape($k); ?>" name="f_<?= html_escape($k); ?>" class="form-select" <?= !$editable?'disabled':''; ?>><option value="">Belum diisi</option><?php
$options=[];if($k==='library_type_id')foreach($types as$t)$options[]=['value'=>$t['id'],'label'=>$t['name'],'parent'=>null];elseif($k==='library_subtype_id')foreach($subtypes as$t)$options[]=['value'=>$t['id'],'label'=>$t['name'].(!$t['iplm_eligible']?' (lokal)':''),'parent'=>$t['library_type_id']];else foreach(json_decode($f['options_json']??'[]',true)?:[]as$o)$options[]=['value'=>$o,'label'=>$o,'parent'=>null];
foreach($options as$o): ?><option value="<?= html_escape($o['value']); ?>" <?= (string)$value===(string)$o['value']?'selected':''; ?> <?= $o['parent']!==null?'data-type="'.(int)$o['parent'].'"':''; ?>><?= html_escape($o['label']); ?></option><?php endforeach; ?></select>
<?php else: ?><input id="f_<?= html_escape($k); ?>" class="form-control" name="f_<?= html_escape($k); ?>" type="<?= $isnum?'number':($f['kind']==='url'?'url':'text'); ?>" <?= $isnum?'min="0" max="999999999999999" step="1"':'maxlength="2000"'; ?> value="<?= html_escape($value); ?>" <?= !$editable?'readonly':''; ?>><?php endif; ?>
<?php if($f['definition']): ?><div class="form-hint mt-1" style="white-space:pre-line"><?= html_escape($f['definition']); ?></div><?php endif; ?>
</div><div><?php if($f['evidence_hint']||$f['evidence_required']): ?><div class="iplm-evidence"><div class="form-label"><i class="ti ti-files me-1" aria-hidden="true"></i>Jenis bukti dukung</div><p class="small mb-2">Simpan dokumen ini dalam satu folder bukti. Tautan folder cukup diisi sekali pada tab <strong>Bukti dukung</strong>.</p><details class="mt-3" open><summary>Dokumen yang perlu disiapkan</summary><p class="small text-secondary mb-0"><?= html_escape($f['evidence_hint']); ?></p></details></div><?php elseif($section==='identity'): ?><div class="form-hint">Identitas induk tetap aman. Perbedaan isian akan ditandai untuk verifikasi admin kabupaten.</div><?php endif; ?></div>
</div><?php endforeach; ?></div></section><?php endforeach; ?>
<?php if($editable): ?><div class="card card-body mb-3 iplm-form-footer"><div class="btn-list"><button name="action" value="draft" class="btn btn-outline-primary">Simpan draft</button><button name="action" value="submit" class="btn btn-primary" <?= $period['state']!=='open'||!$period['dates_confirmed']?'disabled':''; ?>>Simpan & kirim untuk verifikasi</button></div><small class="text-secondary mt-2">Semua tab disimpan sekaligus. Tanda * wajib saat dikirim. Berpindah tab tidak menyimpan atau menghilangkan isian.</small></div><?php endif; ?></form>
