<details class="card card-body mb-3"><summary>Riwayat tindakan (50 terakhir)</summary><ul class="mt-2"><?php foreach($history as$h): ?><li><?= html_escape($h['created_at'].' · '.$h['event'].' · petugas #'.$h['actor_id']); ?></li><?php endforeach; ?></ul></details>
</div></div>
<script>
document.addEventListener('DOMContentLoaded',function(){const button=document.getElementById('use-collection-reference');if(button)button.addEventListener('click',function(){if(!confirm('Pastikan data katalog lengkap dan sesuai akhir periode. Ganti tiga isian koleksi dengan angka tercatat?'))return;const values=<?= json_encode($reference,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;for(const key in values){const field=document.getElementById('f_'+key);if(field)field.value=values[key];}});});
document.addEventListener('DOMContentLoaded',function(){const type=document.getElementById('f_library_type_id'),sub=document.getElementById('f_library_subtype_id');if(!type||!sub)return;function update(reset){for(const option of sub.options){const match=!option.value||option.dataset.type===type.value;option.hidden=!match;option.disabled=!match;}if(reset&&sub.selectedOptions[0]&&sub.selectedOptions[0].disabled)sub.value='';}update(false);type.addEventListener('change',()=>update(true));});
</script>
